// Shoots the staged desktop (stage/desktop.html) at 2× — the "screen" Skryn captures — and
// exports the rects the director aims at, in screen points (1280×720, top-left origin).
//   node shoot.mjs → assets/desk-0.png (before), assets/desk-1.png (after the paste), assets/rects.json
import { chromium } from "playwright";
import { writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const url = pathToFileURL(new URL("stage/desktop.html", import.meta.url).pathname).href;
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 2 });

await page.goto(url);
await page.evaluate(() => document.fonts.ready);
await page.screenshot({ path: "assets/desk-0.png" });

const ids = ["browser", "page", "navSettings", "tabKeys", "warn", "rowProd", "keyProd", "rowTest", "keyTest",
  "copyTest", "chat", "composer", "shot"];
