  const r = document.getElementById(id).getBoundingClientRect();
  return [id, { x: r.x, y: r.y, w: r.width, h: r.height }];
})), ids);

await page.goto(url + "?after");
await page.evaluate(() => document.fonts.ready);
await page.screenshot({ path: "assets/desk-1.png" });

writeFileSync("assets/rects.json", JSON.stringify(rects, null, 2));
await browser.close();
console.log("→ assets/desk-0.png, desk-1.png, rects.json");
EOF
