        guard dur > 0 else { return t >= t0 ? to : from }
        return lerp(from, to, ease(clamp01((t - t0) / dur)))
    }

    func go(_ target: Double, at t: Double, dur: Double, ease: @escaping (Double) -> Double = easeInOut) {
        from = value(t)
        to = target
        t0 = t
        self.dur = dur
        self.ease = ease
    }

    func set(_ v: Double, at t: Double) { go(v, at: t, dur: 0) }
}

// MARK: - Drawing helpers (the frame context is top-left origin, y down)

func rgb(_ hex: UInt32, _ a: CGFloat = 1) -> NSColor {
    NSColor(srgbRed: CGFloat((hex >> 16) & 0xff) / 255, green: CGFloat((hex >> 8) & 0xff) / 255,
            blue: CGFloat(hex & 0xff) / 255, alpha: a)
}

func font(_ size: CGFloat, _ weight: NSFont.Weight = .bold) -> NSFont {
    NSFont.systemFont(ofSize: size, weight: weight)
}

func attr(_ s: String, _ f: NSFont, _ c: NSColor, kern: CGFloat = 0) -> NSAttributedString {
    NSAttributedString(string: s, attributes: [.font: f, .foregroundColor: c, .kern: kern])
}

/// Draws a CGImage into `rect` of a flipped (top-left origin) context without turning it upside down.
func drawImage(_ ctx: CGContext, _ img: CGImage, in rect: CGRect) {
    ctx.saveGState()
    ctx.translateBy(x: rect.minX, y: rect.maxY)
    ctx.scaleBy(x: 1, y: -1)
    ctx.draw(img, in: CGRect(origin: .zero, size: rect.size))
    ctx.restoreGState()
}

func roundedPath(_ r: CGRect, _ radius: CGFloat) -> CGPath {
    CGPath(roundedRect: r, cornerWidth: min(radius, r.width / 2), cornerHeight: min(radius, r.height / 2), transform: nil)
}

/// Draws an attributed string centered on `center`.
func drawCentered(_ s: NSAttributedString, at center: CGPoint) {
    let size = s.size()
    s.draw(at: CGPoint(x: center.x - size.width / 2, y: center.y - size.height / 2))
}

func loadCG(_ path: String) -> CGImage {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil),
          let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { fatalError("can't load \(path)") }
    return img
}

func writePNG(_ img: CGImage, _ path: String) {
    let url = URL(fileURLWithPath: path) as CFURL
    guard let dest = CGImageDestinationCreateWithURL(url, "public.png" as CFString, 1, nil) else { return }
    CGImageDestinationAddImage(dest, img, nil)
    CGImageDestinationFinalize(dest)
}

/// A bitmap context with a top-left origin, and AppKit drawing routed into it.
func makeContext(_ w: Int, _ h: Int) -> CGContext {
    let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedFirst.rawValue | CGBitmapInfo.byteOrder32Little.rawValue)!
    ctx.translateBy(x: 0, y: CGFloat(h))
    ctx.scaleBy(x: 1, y: -1)
    ctx.interpolationQuality = .high
    return ctx
}

func withAppKit(_ ctx: CGContext, _ body: () -> Void) {
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(cgContext: ctx, flipped: true)
    body()
    NSGraphicsContext.restoreGraphicsState()
}

