import AppKit

/// Hosts the real AnnotationView offscreen. Skryn reads the pointer through
/// `mouseLocationOutsideOfEventStream` (badges, T), so the window reports the scripted cursor.
final class StageWindow: NSWindow {
    var scriptedMouse: NSPoint = .zero
    override var mouseLocationOutsideOfEventStream: NSPoint { scriptedMouse }
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { true }
}

/// The app under test: Skryn's own AnnotationView, sized and placed exactly like AnnotationWindow
/// does it (screenshot scaled to fit the screen inset by 8% per side, centered), fed synthetic events.
final class Skryn {
    let screen: CGSize
    let frame: CGRect          // annotation window, in screen points (top-left origin)
    let view: AnnotationView
    let window: StageWindow
    private(set) var dirty = true
    private var cached: CGImage?
    private var lastDigit = Date.distantPast
    static let renderScale: CGFloat = 3

    init(screenshot: NSImage, screen: CGSize) {
        self.screen = screen
        let maxW = screen.width * 0.84, maxH = screen.height * 0.84
        let img = screenshot.size
        let s = (img.width <= maxW && img.height <= maxH) ? 1 : min(maxW / img.width, maxH / img.height)
        let size = CGSize(width: img.width * s, height: img.height * s)
        frame = CGRect(x: (screen.width - size.width) / 2, y: (screen.height - size.height) / 2,
                       width: size.width, height: size.height)
        window = StageWindow(contentRect: NSRect(x: -20000, y: -20000, width: size.width, height: size.height),
                             styleMask: .borderless, backing: .buffered, defer: false)
        window.isReleasedWhenClosed = false
        view = AnnotationView(frame: NSRect(origin: .zero, size: size), screenshot: screenshot)
        window.contentView = view
        window.orderFrontRegardless()
        window.makeFirstResponder(view)
    }

    /// Screenshot point (= screen point of the captured desktop) → where it shows on screen now.
    func onScreen(_ p: CGPoint) -> CGPoint {
        let s = frame.width / screen.width
        return CGPoint(x: frame.minX + p.x * s, y: frame.minY + p.y * s)
    }

    private func windowPoint(_ p: CGPoint) -> NSPoint {
        NSPoint(x: p.x - frame.minX, y: frame.height - (p.y - frame.minY))
    }

    // MARK: input

    func mouse(_ type: NSEvent.EventType, at p: CGPoint, mods: NSEvent.ModifierFlags = []) {
        let wp = windowPoint(p)
        window.scriptedMouse = wp
        guard let e = NSEvent.mouseEvent(with: type, location: wp, modifierFlags: mods, timestamp: 0,
                                         windowNumber: window.windowNumber, context: nil, eventNumber: 0,
                                         clickCount: 1, pressure: type == .leftMouseUp ? 0 : 1) else { return }
        switch type {
        case .leftMouseDown: view.mouseDown(with: e)
        case .leftMouseDragged: view.mouseDragged(with: e)
        case .leftMouseUp: view.mouseUp(with: e)
        default: view.mouseMoved(with: e)
        }
        if view.needsDisplay || type != .mouseMoved { dirty = true }
    }

    private func keyEvent(_ chars: String, _ code: UInt16, _ mods: NSEvent.ModifierFlags) -> NSEvent {
        NSEvent.keyEvent(with: .keyDown, location: .zero, modifierFlags: mods, timestamp: 0,
                         windowNumber: window.windowNumber, context: nil, characters: chars,
                         charactersIgnoringModifiers: chars, isARepeat: false, keyCode: code)!
    }

    /// A plain key press, routed like the window server would: to the first responder
    /// (AnnotationView, or the text view while typing).
    func key(_ chars: String, _ code: UInt16) {
        if Self.digitCodes.contains(code) {
            // Skryn combines digits pressed within 0.5 s of wall time (1, 2 → 12). The renderer
            // runs faster than real time, so separate badges need a real pause between them.
            let dt = Date().timeIntervalSince(lastDigit)
            if dt < 0.6 { Thread.sleep(forTimeInterval: 0.6 - dt) }
            lastDigit = Date()
        }
        window.sendEvent(keyEvent(chars, code, []))
        dirty = true
    }

    /// A Command/Option/Control combo — AppKit offers these to views as key equivalents first.
    func keyEquivalent(_ chars: String, _ code: UInt16, _ mods: NSEvent.ModifierFlags) {
        _ = view.performKeyEquivalent(with: keyEvent(chars, code, mods))
        dirty = true
    }

    /// Cmd+Z / Cmd+Shift+Z — the main menu sends these actions down the responder chain.
    func undo() { view.undo(nil); dirty = true }
    func redo() { view.redo(nil); dirty = true }

    static let digitCodes: Set<UInt16> = [18, 19, 20, 21, 23, 22, 26, 28, 25, 29]

    // MARK: output

    var textView: NSTextView? { view.subviews.compactMap { $0 as? NSTextView }.first }

    /// The insertion point while typing, in screen points (NSTextView blinks it on a timer we never run).
    var caret: CGRect? {
        guard let tv = textView else { return nil }
        let r = tv.firstRect(forCharacterRange: tv.selectedRange(), actualRange: nil)
        let inWindow = window.convertFromScreen(r)
        let x = frame.minX + inWindow.minX
        let y = frame.minY + (frame.height - inWindow.maxY)
        let h = tv.font.map { $0.ascender - $0.descender } ?? inWindow.height
        return CGRect(x: x, y: y, width: max(2, h / 14), height: h)
    }

    /// The window's current pixels (AnnotationView.draw + its text view), rendered at 3×.
    func image() -> CGImage {
        if !dirty, let cached { return cached }
        let b = view.bounds
        let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: Int((b.width * Self.renderScale).rounded()),
                                   pixelsHigh: Int((b.height * Self.renderScale).rounded()), bitsPerSample: 8,
                                   samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                                   bytesPerRow: 0, bitsPerPixel: 0)!
        rep.size = b.size
        view.cacheDisplay(in: b, to: rep)
        cached = rep.cgImage!
        dirty = false
        view.needsDisplay = false
        return cached!
    }
}

