import AppKit

let videoW = 1920, videoH = 1080
let screenSize = CGSize(width: 1280, height: 720)

/// Per-topic stage backgrounds (same pastel family as the Skrami promo).
enum Backdrop: CaseIterable {
    case paper, blue, peach, green, lavender, yellow, mint

    var colors: (base: UInt32, a: UInt32, b: UInt32) {
        switch self {
        case .paper: return (0xf3f1ec, 0xe6e0f5, 0xf7e3d6)
        case .blue: return (0xd6e4f5, 0x92baec, 0xf0f6fd)
        case .peach: return (0xf5ddca, 0xeeaa76, 0xfdf3eb)
        case .green: return (0xd6edd5, 0x92d096, 0xf0f9f0)
        case .lavender: return (0xe0daf3, 0xb0a0e8, 0xf5f2fd)
        case .yellow: return (0xf6eac0, 0xfad669, 0xfff8de)
        case .mint: return (0xd0ece7, 0x7ecec2, 0xeef9f7)
        }
    }

    func render() -> CGImage {
        let ctx = makeContext(videoW, videoH)
        let c = colors
        ctx.setFillColor(rgb(c.base).cgColor)
        ctx.fill(CGRect(x: 0, y: 0, width: videoW, height: videoH))
        func blob(_ color: UInt32, _ alpha: CGFloat, _ center: CGPoint, _ radius: CGFloat) {
            let g = CGGradient(colorsSpace: CGColorSpace(name: CGColorSpace.sRGB),
                               colors: [rgb(color, alpha).cgColor, rgb(color, 0).cgColor] as CFArray,
                               locations: [0, 1])!
            ctx.drawRadialGradient(g, startCenter: center, startRadius: 0, endCenter: center, endRadius: radius, options: [])
        }
        blob(c.a, 0.55, CGPoint(x: 80, y: 0), 1300)
        blob(c.a, 0.5, CGPoint(x: 1920, y: 1080), 1200)
        blob(c.b, 0.75, CGPoint(x: 1340, y: 320), 900)
        return ctx.makeImage()!
    }
}

enum HUDItem {
    case key(String)
    case label(String)
    case gap
}

/// Everything on screen that isn't the app itself: camera, desktop, cursor, captions, keycaps, cards.
final class Stage {
    var t = 0.0

    // camera: `focus` (screen points) lands on `anchor` (video px), `zoom` = video px per screen point
    let camX = Tween(640), camY = Tween(360), camZ = Tween(log(1.22))
    let anchor = CGPoint(x: 960, y: 612)
    var zoom: CGFloat { exp(camZ.value(t)) }

    func camera(_ focus: CGPoint, zoom z: Double, dur: Double) {
        camX.go(focus.x, at: t, dur: dur)
        camY.go(focus.y, at: t, dur: dur)
        camZ.go(log(z), at: t, dur: dur)
    }

    func v(_ p: CGPoint) -> CGPoint {
        let z = zoom
        return CGPoint(x: (p.x - camX.value(t)) * z + anchor.x, y: (p.y - camY.value(t)) * z + anchor.y)
    }

    func v(_ r: CGRect) -> CGRect {
        let o = v(r.origin)
        return CGRect(x: o.x, y: o.y, width: r.width * zoom, height: r.height * zoom)
    }

    // desktop
    var screens: [CGImage] = []
    var screenIndex = 0
    let deskAlpha = Tween(1)
    let deskChrome = Tween(1)   // display frame (rounded corners + shadow) vs. full bleed

    // app
    var app: Skryn?
    var appVisible = false

    // pasted image in the chat
    var pasted: CGImage?
    var pasteT0 = 0.0
    var shotRect = CGRect.zero

    // cursor (screen points)
    var cursor = CGPoint(x: 640, y: 400)
    var cursorDown = false
    var cursorHidden = false
    var cursorShape: NSCursor = .arrow
    let cursorAlpha = Tween(1)
    var caretVisible = false

    // backdrop
    private var backdrops: [Backdrop: CGImage] = [:]
    private var bgFrom = Backdrop.paper, bgTo = Backdrop.paper, bgT0 = -10.0

    // captions
    private var caption: (text: String, t0: Double)?
    private var oldCaption: (text: String, t0: Double)?
    private let dim = Tween(0)
    private var dimColor = Backdrop.paper

    // keycaps
    private var hud: (items: [HUDItem], t0: Double)?
    private var oldHud: (items: [HUDItem], t0: Double)?
    var pressed: Set<Int> = []

    // cards
    let titleAlpha = Tween(1)
    let endAlpha = Tween(0)
    private let icon: CGImage

    init(desks: [CGImage], icon: CGImage) {
        self.icon = icon
        for b in Backdrop.allCases { backdrops[b] = b.render() }
        screens = desks.map(Self.withMenuBar)
    }

    // MARK: - direction

    /// Topic change: the stage dims to the new color with the caption big in the middle, then it docks on top.
    func topic(_ text: String, _ bg: Backdrop) {
        bgFrom = currentBackdrop
        bgTo = bg
        bgT0 = t
        dimColor = bg
        dim.go(0.9, at: t, dur: 0.3)
        dim.go(0, at: t + 1.0, dur: 0.55)
        if let caption { oldCaption = (caption.text, t) }
        caption = (text, t + 0.15)
    }

    private var currentBackdrop: Backdrop { t - bgT0 < 0.4 ? bgFrom : bgTo }

    func backdrop(_ bg: Backdrop, dur: Double = 0.8) {
        bgFrom = currentBackdrop
        bgTo = bg
        bgT0 = t
    }

    func clearCaption() {
        if let caption { oldCaption = (caption.text, t) }
        caption = nil
    }

    func showHUD(_ items: [HUDItem]) {
        if let hud { oldHud = (hud.items, t) }
        hud = (items, t)
        pressed = []
    }

    func hideHUD() {
        if let hud { oldHud = (hud.items, t) }
        hud = nil
        pressed = []
    }

    // MARK: - frame

    func render(into ctx: CGContext) {
        // backdrop
        let bgP = clamp01((t - bgT0) / 0.8)
        ctx.setAlpha(1)
        drawImage(ctx, backdrops[bgFrom]!, in: CGRect(x: 0, y: 0, width: videoW, height: videoH))
        if bgP > 0 {
            ctx.setAlpha(bgP)
            drawImage(ctx, backdrops[bgTo]!, in: CGRect(x: 0, y: 0, width: videoW, height: videoH))
            ctx.setAlpha(1)
        }

        // content, fading out under the caption band
        ctx.beginTransparencyLayer(auxiliaryInfo: nil)
        drawDesktop(ctx)
        drawApp(ctx)
        drawCursor(ctx)
        ctx.setBlendMode(.destinationIn)
        let mask = CGGradient(colorsSpace: CGColorSpace(name: CGColorSpace.sRGB),
                              colors: [NSColor(white: 0, alpha: 0).cgColor, NSColor(white: 0, alpha: 1).cgColor] as CFArray,
                              locations: [0, 1])!
        ctx.drawLinearGradient(mask, start: CGPoint(x: 0, y: 118), end: CGPoint(x: 0, y: 164),
                               options: [.drawsAfterEndLocation])
        ctx.setBlendMode(.normal)
        ctx.endTransparencyLayer()

        drawHUD(ctx)

        // dim + captions
        let d = dim.value(t)
        if d > 0 {
            ctx.setFillColor(rgb(dimColor.colors.base, d).cgColor)
            ctx.fill(CGRect(x: 0, y: 0, width: videoW, height: videoH))
        }
        drawCards(ctx)
        drawCaptions(ctx)
    }

    private func drawDesktop(_ ctx: CGContext) {
        let a = deskAlpha.value(t)
        guard a > 0.001 else { return }
        let r = v(CGRect(origin: .zero, size: screenSize))
        let chrome = deskChrome.value(t)
        let radius = 14 * chrome * zoom / 1.22
        ctx.saveGState()
        ctx.setAlpha(a)
        ctx.beginTransparencyLayer(auxiliaryInfo: nil)
        if chrome > 0.01 {
            ctx.saveGState()
            ctx.setShadow(offset: CGSize(width: 0, height: 22 * chrome), blur: 60 * chrome,
                          color: NSColor(white: 0.1, alpha: 0.28 * chrome).cgColor)
            ctx.addPath(roundedPath(r, radius))
            ctx.setFillColor(NSColor.white.cgColor)
            ctx.fillPath()
            ctx.restoreGState()
        }
        ctx.saveGState()
        ctx.addPath(roundedPath(r, radius))
        ctx.clip()
        drawImage(ctx, screens[screenIndex], in: r)
        drawPasted(ctx)
        ctx.restoreGState()
        ctx.endTransparencyLayer()
        ctx.restoreGState()
    }

    private func drawPasted(_ ctx: CGContext) {
        guard let pasted else { return }
        let p = clamp01((t - pasteT0) / 0.32)
        guard p > 0 else { return }
        let s = lerp(0.9, 1, easeOutBack(p))
        let base = v(shotRect)
        let r = CGRect(x: base.maxX - base.width * s, y: base.maxY - base.height * s,
                       width: base.width * s, height: base.height * s)
        ctx.saveGState()
        ctx.setAlpha(clamp01(p * 2))
        ctx.addPath(roundedPath(r, 14 * zoom))
        ctx.clip()
        drawImage(ctx, pasted, in: r)
        ctx.restoreGState()
        ctx.saveGState()
        ctx.setAlpha(clamp01(p * 2))
        ctx.addPath(roundedPath(r, 14 * zoom))
        ctx.setStrokeColor(NSColor(white: 0, alpha: 0.12).cgColor)
        ctx.setLineWidth(1)
        ctx.strokePath()
        ctx.restoreGState()
    }

    private func drawApp(_ ctx: CGContext) {
        guard appVisible, let app else { return }
        let r = v(app.frame)
        let radius = 10 * zoom
        ctx.saveGState()
        // macOS window shadow (hasShadow = true) + hairline border
        ctx.setShadow(offset: CGSize(width: 0, height: 16 * zoom / 1.4), blur: 48 * zoom / 1.4,
                      color: NSColor(white: 0, alpha: 0.4).cgColor)
        ctx.addPath(roundedPath(r, radius))
        ctx.setFillColor(NSColor.black.cgColor)
        ctx.fillPath()
        ctx.restoreGState()
        ctx.saveGState()
        ctx.addPath(roundedPath(r, radius))  // the view's layer cornerRadius = 10
        ctx.clip()
        drawImage(ctx, app.image(), in: r)
        if caretVisible, let c = app.caret, Int(t * 2) % 2 == 0 || t.truncatingRemainder(dividingBy: 1) < 0.5 {
            ctx.setFillColor(AnnotationColor.red.nsColor.cgColor)
            ctx.fill(v(c))
        }
        ctx.restoreGState()
        ctx.saveGState()
        ctx.addPath(roundedPath(r.insetBy(dx: 0.5, dy: 0.5), radius))
        ctx.setStrokeColor(NSColor(white: 0, alpha: 0.25).cgColor)
        ctx.setLineWidth(1)
        ctx.strokePath()
        ctx.restoreGState()
    }

    private func drawCursor(_ ctx: CGContext) {
        let a = cursorAlpha.value(t)
        guard !cursorHidden, a > 0.001 else { return }
        let img = cursorShape.image
        let hot = cursorShape.hotSpot
        let cs = min(zoom, 1.9) * (cursorDown ? 0.9 : 1)
        let p = v(cursor)
        let r = CGRect(x: p.x - hot.x * cs, y: p.y - hot.y * cs, width: img.size.width * cs, height: img.size.height * cs)
        ctx.saveGState()
        ctx.setAlpha(a)
        withAppKit(ctx) {
            img.draw(in: r, from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: nil)
        }
        ctx.restoreGState()
    }

    // MARK: captions

    private let dockY: CGFloat = 84

    private func drawCaptions(_ ctx: CGContext) {
        if let old = oldCaption {
            let p = clamp01((t - old.t0) / 0.25)
            if p < 1 { drawCaption(ctx, old.text, center: CGPoint(x: 960, y: dockY - 8 * p), scale: 1, alpha: 1 - p) }
        }
        guard let c = caption, t >= c.t0 else { return }
        let appear = clamp01((t - c.t0) / 0.3)
        let dock = easeInOut(clamp01((t - c.t0 - 0.85) / 0.7))
        let y = lerp(540, dockY, dock)
        let s = lerp(1.55, 1, dock) * lerp(0.96, 1, easeOut(appear))
        drawCaption(ctx, c.text, center: CGPoint(x: 960, y: y), scale: s, alpha: appear)
    }

    private func drawCaption(_ ctx: CGContext, _ text: String, center: CGPoint, scale: CGFloat, alpha: CGFloat) {
        let s = attr(text, font(50, .bold), rgb(0x1d1d1f), kern: -0.6)
        ctx.saveGState()
        ctx.setAlpha(alpha)
        ctx.translateBy(x: center.x, y: center.y)
        ctx.scaleBy(x: scale, y: scale)
        withAppKit(ctx) { drawCentered(s, at: .zero) }
        ctx.restoreGState()
    }

    // MARK: keycaps

    private func drawHUD(_ ctx: CGContext) {
        if let old = oldHud {
            let p = clamp01((t - old.t0) / 0.22)
            if p < 1 { drawHUD(ctx, old.items, alpha: 1 - p, dy: -8 * p, scale: 1, pressed: []) }
        }
        guard let h = hud else { return }
        let p = clamp01((t - h.t0) / 0.28)
        drawHUD(ctx, h.items, alpha: clamp01(p * 1.6), dy: 16 * (1 - easeOut(p)), scale: lerp(0.94, 1, easeOutBack(p)),
                pressed: pressed)
    }

    private func drawHUD(_ ctx: CGContext, _ items: [HUDItem], alpha: CGFloat, dy: CGFloat, scale: CGFloat,
                         pressed: Set<Int>) {
        let capH: CGFloat = 58, pad: CGFloat = 12, gap: CGFloat = 10
        let keyFont = font(28, .semibold), labelFont = font(28, .semibold)
        var widths: [CGFloat] = []
        for item in items {
            switch item {
            case .key(let k):
                let w = attr(k, k.count > 1 ? font(22, .semibold) : keyFont, .black).size().width
                widths.append(max(capH, w + 30))
            case .label(let l): widths.append(attr(l, labelFont, .white).size().width + 8)
            case .gap: widths.append(22)
            }
        }
        let inner = widths.reduce(0, +) + gap * CGFloat(max(items.count - 1, 0))
        let box = CGRect(x: -inner / 2 - pad - 6, y: -capH / 2 - pad, width: inner + 2 * pad + 18, height: capH + 2 * pad)
        ctx.saveGState()
        ctx.setAlpha(alpha)
        ctx.translateBy(x: 960, y: 990 + dy)
        ctx.scaleBy(x: scale, y: scale)
        ctx.saveGState()
        ctx.setShadow(offset: CGSize(width: 0, height: 14), blur: 36, color: NSColor(white: 0.05, alpha: 0.4).cgColor)
        ctx.addPath(roundedPath(box, 20))
        ctx.setFillColor(rgb(0x1f2329, 0.94).cgColor)
        ctx.fillPath()
        ctx.restoreGState()
        var x = -inner / 2 + 3
        withAppKit(ctx) {
            for (i, item) in items.enumerated() {
                let w = widths[i]
                switch item {
                case .key(let k):
                    let down = pressed.contains(i)
                    let depth: CGFloat = down ? 2 : 5
                    let r = CGRect(x: x, y: -capH / 2 + (down ? 3 : 0), width: w, height: capH - (down ? 3 : 0))
                    NSColor(white: 0.72, alpha: 1).setFill()
                    NSBezierPath(roundedRect: r, xRadius: 11, yRadius: 11).fill()
                    NSColor.white.setFill()
                    NSBezierPath(roundedRect: CGRect(x: r.minX, y: r.minY, width: r.width, height: r.height - depth),
                                 xRadius: 11, yRadius: 11).fill()
                    let f = k.count > 1 ? font(22, .semibold) : keyFont
                    drawCentered(attr(k, f, rgb(0x1f2329)), at: CGPoint(x: r.midX, y: r.minY + (r.height - depth) / 2))
                case .label(let l):
                    let s = attr(l, labelFont, .white)
                    s.draw(at: CGPoint(x: x + 8, y: -s.size().height / 2))
                case .gap:
                    NSColor(white: 1, alpha: 0.25).setFill()
                    NSBezierPath(rect: CGRect(x: x + w / 2 - 1, y: -capH / 2 + 10, width: 2, height: capH - 20)).fill()
                }
                x += w + gap
            }
        }
        ctx.restoreGState()
    }

    // MARK: cards

    private func drawCards(_ ctx: CGContext) {
        let ta = titleAlpha.value(t), ea = endAlpha.value(t)
        if ta > 0.001 { drawCard(ctx, alpha: ta, sub: "Screenshot & Annotate menu bar app", url: nil) }
        if ea > 0.001 { drawCard(ctx, alpha: ea, sub: "Native macOS. No account required.", url: "skryn.app") }
    }

    private func drawCard(_ ctx: CGContext, alpha: CGFloat, sub: String, url: String?) {
        ctx.saveGState()
        ctx.setAlpha(alpha)
        drawImage(ctx, backdrops[.paper]!, in: CGRect(x: 0, y: 0, width: videoW, height: videoH))
        let top: CGFloat = url == nil ? 290 : 250
        drawImage(ctx, icon, in: CGRect(x: 960 - 105, y: top, width: 210, height: 210))
        withAppKit(ctx) {
            drawCentered(attr("Skryn", font(120, .bold), rgb(0x1d1d1f), kern: -2.5), at: CGPoint(x: 960, y: top + 300))
            drawCentered(attr(sub, font(40, .medium), rgb(0x55555c), kern: -0.3), at: CGPoint(x: 960, y: top + 398))
            if let url {
                let s = attr(url, font(34, .semibold), rgb(0x1d1d1f))
                let w = s.size().width + 56
                let pill = CGRect(x: 960 - w / 2, y: top + 460, width: w, height: 68)
                NSColor(white: 1, alpha: 0.8).setFill()
                NSBezierPath(roundedRect: pill, xRadius: 34, yRadius: 34).fill()
                NSColor(white: 0, alpha: 0.08).setStroke()
                NSBezierPath(roundedRect: pill.insetBy(dx: 0.5, dy: 0.5), xRadius: 34, yRadius: 34).stroke()
                drawCentered(s, at: CGPoint(x: pill.midX, y: pill.midY))
            }
        }
        ctx.restoreGState()
    }

    // MARK: menu bar

    /// Desk shot (2×) + a menu bar with Skryn's real status item symbol.
    static func withMenuBar(_ desk: CGImage) -> CGImage {
        let ctx = makeContext(desk.width, desk.height)
        drawImage(ctx, desk, in: CGRect(x: 0, y: 0, width: desk.width, height: desk.height))
        ctx.scaleBy(x: 2, y: 2)
        ctx.setFillColor(NSColor(white: 1, alpha: 0.32).cgColor)
        ctx.fill(CGRect(x: 0, y: 0, width: screenSize.width, height: 24))
        let ink = NSColor(white: 0.08, alpha: 0.9)
        withAppKit(ctx) {
            var x = screenSize.width - 14
            let clock = attr("Tue Sep 29  10:41", font(13, .medium), ink)
            x -= clock.size().width
            clock.draw(at: CGPoint(x: x, y: 12 - clock.size().height / 2))
            for name in ["switch.2", "wifi", "battery.100percent", "camera"] {
                let config = NSImage.SymbolConfiguration(pointSize: name == "battery.100percent" ? 13 : 14, weight: .regular)
                guard let sym = NSImage(systemSymbolName: name, accessibilityDescription: nil)?
                    .withSymbolConfiguration(config) else { continue }
                x -= 20 + sym.size.width
                let r = CGRect(x: x, y: 12 - sym.size.height / 2, width: sym.size.width, height: sym.size.height)
                let tinted = NSImage(size: sym.size, flipped: false) { rect in
                    sym.draw(in: rect)
                    ink.set()
                    rect.fill(using: .sourceAtop)
                    return true
                }
                tinted.draw(in: r, from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: nil)
            }
        }
        return ctx.makeImage()!
    }
}

