/// Streams raw BGRA frames into ffmpeg (H.264, 60 fps constant).
final class Encoder {
    private let proc = Process()
    private let pipe = Pipe()

    init(path: String) {
        proc.executableURL = URL(fileURLWithPath: "/opt/homebrew/bin/ffmpeg")
