# The app icon (docs/icon.png) sits on an opaque white square; knock the white out so it can
# stand on the pastel cards. Flood fill from the corners only — the icon's own whites stay.
#   uv run --with pillow icon.py ../docs/icon.png assets/icon-cut.png
import sys
from PIL import Image, ImageDraw

im = Image.open(sys.argv[1]).convert("RGBA")
w, h = im.size
key = (255, 0, 255, 255)
flat = im.copy()
for xy in [(0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)]:
    ImageDraw.floodfill(flat, xy, key, thresh=24)
px, out = flat.load(), im.load()
for y in range(h):
    for x in range(w):
        if px[x, y] == key:
            out[x, y] = (0, 0, 0, 0)
im.save(sys.argv[2])
