cp promo/poster.jpg docs/promo-poster.jpg && cat > promo/build/check-site.mjs <<'EOF'
// Loads docs/ in WebKit (H.264 like Safari; Playwright's Chromium has no proprietary codecs),
// plays the demo muted for 2 s, and screenshots desktop + phone layouts.
import { webkit } from "playwright";
import { createServer } from "node:http";
import { readFileSync } from "node:fs";
const docs = new URL("../../docs/", import.meta.url).pathname;
const srv = createServer((q, s) => {
  const p = q.url === "/" ? "index.html" : q.url.slice(1);
  try { s.end(readFileSync(docs + p)); } catch { s.statusCode = 404; s.end(); }
}).listen(5191);
const browser = await webkit.launch();
for (const [name, vp] of [["desktop", { width: 1440, height: 1000 }], ["phone", { width: 390, height: 844 }]]) {
  const page = await browser.newPage({ viewport: vp, deviceScaleFactor: 2 });
  await page.goto("http://127.0.0.1:5191/");
  await page.waitForFunction(() => document.querySelector(".demo video").complete !== false);
  await page.screenshot({ path: `build/site-${name}.png` });
  const box = await page.locator(".demo video").boundingBox();
  const r = await page.evaluate(async () => {
    const v = document.querySelector(".demo video");
    v.muted = true;
    await v.play();
    await new Promise((ok) => setTimeout(ok, 2000));
    const out = { t: v.currentTime.toFixed(2), w: v.videoWidth, h: v.videoHeight, dur: v.duration.toFixed(2), err: v.error?.code ?? null };
    v.currentTime = 30;
    await new Promise((ok) => v.addEventListener("seeked", ok, { once: true }));
    out.seeked = v.currentTime.toFixed(2);
    return out;
  });
  console.log(name, JSON.stringify({ box: { x: Math.round(box.x), w: Math.round(box.width), h: Math.round(box.height) }, ...r }));
  await page.close();
}
await browser.close();
srv.close();
EOF
cd promo && node build/check-site.mjs

